void StartDownloadItem(download::DownloadCreateInfo* info,
                       const download::DownloadUrlParameters::OnStartedCallback& on_started,
                       download::InProgressDownloadItem* callback,
                       uint32_t id) {
  // Ensure that this function is called on the UI thread
  CHECK(IsOnUIThread());

  // Create a new active download item
  download::DownloadItem* download_item = new download::DownloadItem(id, info);

  // Notify observers about the new download
  NotifyDownloadCreated(download_item);

  // Call OnDownloadStarted with the new download item and the provided callback
  OnDownloadStarted(download_item, on_started, callback);
}

void StartDownloadItem(download::DownloadCreateInfo* info,
                       const download::DownloadUrlParameters::OnStartedCallback& on_started,
                       download::InProgressDownloadItemCallback callback,
                       uint32_t id) {
  // Check if the function is called on the UI thread
  if (!IsOnUIThread()) {
    return;
  }

  // Create a new download item
  DownloadItem* download_item = CreateDownloadItem(info, id);

  // Notify observers of the new download creation
  NotifyDownloadCreated(download_item);

  // Call the OnDownloadStarted function with the download item and callback
  OnDownloadStarted(download_item, on_started);

  // Invoke the provided callback with the new download item
  callback.Run(download_item);
}

void start_download_item(download::DownloadCreateInfo* info,
                         const download::DownloadUrlParameters::OnStartedCallback& on_started,
                         download::InProgressDownloadItemCallback callback,
                         uint32_t id) {
    // Ensure this is called on the UI thread
    DCHECK_CURRENTLY_ON(BrowserThread::UI);

    // Create a new active download item
    download::DownloadItem* download_item = new download::DownloadItem(info, id);

    // Notify observers of the new download
    download_manager_->AddDownload(download_item);

    // Invoke the OnDownloadStarted function with the new download item and the provided callback
    on_started.Run(download_item, callback);
}

void start_download_item(download::DownloadCreateInfo* info,
                         const download::DownloadUrlParameters::OnStartedCallback& on_started,
                         download::InProgressDownloadManager::StartDownloadItemCallback callback,
                         uint32_t id) {
  // Ensure this is called on the UI thread
  DCHECK_CURRENTLY_ON(content::BrowserThread::UI);

  // Create an active download item
  download::DownloadItem* download_item =
      new download::DownloadItem(info, id);

  // Notify observers of the new download
  download_manager()->AddDownload(download_item);

  // Call the provided on_started callback
  if (!on_started.is_null()) {
    on_started.Run(download_item);
  }

  // Execute the provided callback with the new download item
  callback.Run(download_item);
}

void StartDownloadItem(download::DownloadCreateInfo* info,
                       const download::DownloadUrlParameters::OnStartedCallback& on_started,
                       download::InProgressDownloadItemCallback callback,
                       uint32_t id) {
    // Check that this function is called on the UI thread.
    DCHECK_CURRENTLY_ON(content::BrowserThread::UI);

    // Create the new active download item.
    download::DownloadItem* item = CreateActiveDownloadItem(info, id);

    // Notify observers of the new download creation.
    NotifyNewDownload(item);

    // Call the OnDownloadStarted function with the new download item and the provided callback.
    OnDownloadStarted(item, on_started);

    // Invoke the provided callback with the new download item.
    callback.Run(item);
}
